import crypto from "node:crypto";

// Accounts and signed login links. Until UAE PASS and facility sign-on are
// connected, a person signs in with a link generated by `npm run login-links`
// or the protected /access page. Links are HMAC-signed and expire.

export type Role = "person" | "clinician" | "system";

export interface Account {
  role: Role;
  id: string;
  name: string;
  description: string;
}

export const ACCOUNTS: Account[] = [
  { role: "person", id: "noura", name: "Noura Al Mansouri", description: "Resident, 34. Signals after her Health Age check." },
  { role: "person", id: "arjun", name: "Arjun Nair", description: "Resident, 37. Lifestyle signal, planning children soon." },
  { role: "person", id: "maryam", name: "Maryam Haddad", description: "Resident, 29. No signal on record." },
  { role: "clinician", id: "layla", name: "Dr Layla Al Hashimi", description: "Family physician. Signals inbox and reviews." },
  { role: "system", id: "analyst", name: "Department of Health analyst", description: "Evidence and safety report." },
];

export const PERSON_IDS = ACCOUNTS.filter((a) => a.role === "person").map((a) => a.id);

export function findAccount(role: string, id: string): Account | undefined {
  return ACCOUNTS.find((a) => a.role === role && a.id === id);
}

function secret(): string {
  const s = process.env.SESSION_SECRET;
  if (!s && process.env.NODE_ENV === "production") throw new Error("SESSION_SECRET must be set in production");
  return s ?? "masar-development-secret";
}

export function sign(value: string): string {
  return crypto.createHmac("sha256", secret()).update(value).digest("base64url");
}

export function verifySignature(value: string, mac: string): boolean {
  const expected = sign(value);
  return mac.length === expected.length && crypto.timingSafeEqual(Buffer.from(mac), Buffer.from(expected));
}

const DAY = 86_400_000;

/** A login link token: "login.role.id.expiresAt.signature". */
export function createLoginToken(account: Pick<Account, "role" | "id">, ttlDays = 30): string {
  const value = `login.${account.role}.${account.id}.${Date.now() + ttlDays * DAY}`;
  return `${value}.${sign(value)}`;
}

export function verifyLoginToken(token: string): Account | null {
  const parts = token.split(".");
  if (parts.length !== 5 || parts[0] !== "login") return null;
  const [, role, id, expires, mac] = parts;
  if (!verifySignature(parts.slice(0, 4).join("."), mac)) return null;
  if (!Number.isFinite(Number(expires)) || Number(expires) < Date.now()) return null;
  return findAccount(role, id) ?? null;
}

/** How a clinician appears in a person's access log, taken from their account. */
export function clinicianLabel(id: string): string {
  const a = findAccount("clinician", id);
  return a ? `${a.name} (family physician)` : "A clinician";
}

export function homeFor(role: Role): string {
  return role === "person" ? "/me" : role === "clinician" ? "/clinic" : "/system";
}
